import cors from 'cors';

const allowedOrigins = [
  'http://localhost:3000',
  'https://example.com',
];

app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  methods: ['GET', 'HEAD', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

